// ============================================================================
// Analytics API
// ============================================================================

/**
 * Analytics API service for loading analytics data
 */
export const analyticsApi = {
  /**
   * Load analytics report from file system
   *
   * @param outputsPath - Base path to data directory (e.g., '/data')
   * @returns Analytics report or mock data if file doesn't exist
   */
  async loadAnalyticsReport(outputsPath: string): Promise<AnalyticsReport> {
    const path = `${outputsPath}/analytics/analytics_report.json`;

    try {
      const response = await fetch(path);
      if (!response.ok) {
        if (response.status === 404) {
          console.warn(`[analyticsApi] Analytics report not found at ${path}, using mock data`);
          return generateMockAnalyticsReport();
        }
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }

      const text = await response.text();
      const rawData = JSON.parse(text) as unknown;

      if (!validateAnalyticsReport(rawData)) {
        console.warn('[analyticsApi] Analytics report has invalid structure, using mock data');
        return generateMockAnalyticsReport();
      }

      const data = transformAnalyticsReport(rawData);
      console.log(
        `[analyticsApi] Loaded analytics report: ${data.riskData.length} risk items, ${data.insights.length} insights`
      );
      return data;
    } catch (error) {
      console.warn(`[analyticsApi] Error loading analytics report:`, error);
      return generateMockAnalyticsReport();
    }
  },

  /**
   * Load risk data only
   */
  async loadRiskData(outputsPath: string): Promise<RiskData[]> {
    const report = await this.loadAnalyticsReport(outputsPath);
    return report.riskData;
  },

  /**
   * Load debt summary only
   */
  async loadDebtSummary(outputsPath: string): Promise<AnalyticsReport['debtSummary']> {
    const report = await this.loadAnalyticsReport(outputsPath);
    return report.debtSummary;
  },

  /**
   * Load predictions only
   */
  async loadPredictions(outputsPath: string): Promise<AnalyticsReport['predictions']> {
    const report = await this.loadAnalyticsReport(outputsPath);
    return report.predictions;
  },

  /**
   * Load insights only
   */
  async loadInsights(outputsPath: string): Promise<AnalyticsInsight[]> {
    const report = await this.loadAnalyticsReport(outputsPath);
    return report.insights;
  },

  /**
   * Dismiss an insight (mock implementation)
   */
  async dismissInsight(insightId: string): Promise<{ success: boolean }> {
    // In a real implementation, this would call a backend API
    console.log(`[analyticsApi] Dismissing insight: ${insightId}`);
    return { success: true };
  },
};
